ALTER TABLE state_players ADD COLUMN IF NOT EXISTS initial_rating numeric;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS wins integer NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS losses integer NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS draws integer NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS frames_won integer NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS frames_lost integer NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS last_change numeric NOT NULL DEFAULT 0;
ALTER TABLE state_players ADD COLUMN IF NOT EXISTS form jsonb NOT NULL DEFAULT '[]'::jsonb;
UPDATE state_players SET short=COALESCE(short,payload->>'short',left(name,3)), handicap=COALESCE(handicap,(payload->>'handicap')::numeric), colour=COALESCE(colour,payload->>'colour'), initial_rating=COALESCE(initial_rating,(payload->>'initialRating')::numeric,rating), wins=COALESCE((payload->>'wins')::integer,0), losses=COALESCE((payload->>'losses')::integer,0), draws=COALESCE((payload->>'draws')::integer,0), frames_won=COALESCE((payload->>'framesWon')::integer,0), frames_lost=COALESCE((payload->>'framesLost')::integer,0), last_change=COALESCE((payload->>'lastChange')::numeric,0), form=COALESCE(payload->'form','[]'::jsonb);
ALTER TABLE state_players ALTER COLUMN short SET NOT NULL;
ALTER TABLE state_players ALTER COLUMN initial_rating SET NOT NULL;
ALTER TABLE state_players DROP COLUMN IF EXISTS payload;

