UPDATE state_matches SET score_a=(payload->>'scoreA')::integer,score_b=(payload->>'scoreB')::integer,entry_mode=payload->>'entryMode',frame_evidence=(payload->>'frameEvidence')::numeric,performance_score=(payload->>'performanceScore')::numeric,evidence_weight=(payload->>'evidenceWeight')::numeric,handicap_adjustment=(payload->>'handicapAdjustment')::numeric,over_handicap_elo=(payload->>'overHandicapElo')::numeric,over_handicap_multiplier=(payload->>'overHandicapMultiplier')::numeric,high_breaks=COALESCE(payload->'highBreaks','[]'::jsonb),actual=(payload->>'actual')::numeric,giver=payload->>'giver',official=(payload->>'official')::numeric,extra=(payload->>'extra')::numeric,expected_a=(payload->>'expectedA')::numeric,before_a=(payload->>'beforeA')::numeric,before_b=(payload->>'beforeB')::numeric,before_a2=(payload->>'beforeA2')::numeric,before_b2=(payload->>'beforeB2')::numeric,after_a=(payload->>'afterA')::numeric,after_b=(payload->>'afterB')::numeric,after_a2=(payload->>'afterA2')::numeric,after_b2=(payload->>'afterB2')::numeric,delta_a=(payload->>'deltaA')::numeric,margin_multiplier=(payload->>'marginMultiplier')::numeric,created_at=COALESCE((payload->>'createdAt')::timestamptz,updated_at);
