CREATE TABLE IF NOT EXISTS state_settings (id boolean PRIMARY KEY DEFAULT true CHECK (id), data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO state_settings (id,data,updated_at) SELECT true,data->'settings',updated_at FROM app_state WHERE id=1 ON CONFLICT (id) DO NOTHING;
CREATE TABLE IF NOT EXISTS state_audits (id text PRIMARY KEY,text text NOT NULL,occurred_at timestamptz NOT NULL);
INSERT INTO state_audits (id,text,occurred_at) SELECT audit->>'id',audit->>'text',(audit->>'at')::timestamptz FROM app_state,jsonb_array_elements(COALESCE(data->'audits','[]'::jsonb)) audit ON CONFLICT (id) DO NOTHING;
ALTER TABLE state_matches ADD CONSTRAINT state_matches_player_a_fkey FOREIGN KEY (player_a) REFERENCES state_players(id) ON DELETE RESTRICT;
ALTER TABLE state_matches ADD CONSTRAINT state_matches_player_b_fkey FOREIGN KEY (player_b) REFERENCES state_players(id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS state_audits_occurred_at_idx ON state_audits (occurred_at DESC);
